/* where the reader is: the page's folder below the site's root, and the part of the address after # */
export function where(rel, hash) {
  const h = (hash || "").replace(/^#/, ""), k = h.split("=")[0];
  rel = (rel || "").replace(/index\.html$/, "");
  if (rel === "") return "home";
  if (rel === "method/") return "method";
  if (rel === "access/") return "access";
  if (rel === "app/") return "app";
  if (rel === "meet/") return "meet";
  if (rel === "dashboard/") return ({record: "dash_record", states: "dash_states"})[k] || "dash_place";
  if (rel === "rooms.html") return k === "states" ? "rooms_states" : "rooms";
  if (rel === "cabin.html") return "cabin";
  if (rel === "us/") return ({bills: "us_bills", bill: "us_bill", map: "us_map", vote: "us_map", shapes: "us_shapes", shape: "us_shapes",
    people: "us_people", how: "us_how", members: "us_members", member: "us_member", money: "us_money"})[k] || "us_home";
  if (rel === "ballot/") return "b_door";
  if (rel === "ballot/polling-place/") return "b_place";
  if (rel === "ballot/us/") return ({state: "bu_state", race: "bu_race", senate: "bu_senate", sources: "bu_sources"})[k] || "bu_home";
  if (rel === "ballot/states/") return "bs_home";
  if (rel === "ballot/kept/") return "b_kept";
  if (rel === "ballot/faq/") return "b_faq";
  if (rel === "ballot/forecasts/") return "b_fc";
  if (/^ballot\/[a-z]{2}\/$/.test(rel)) return ({statewide: "bx_list", legislature: "bx_list", courts: "bx_list", counties: "bx_counties",
    county: "bx_counties", race: "bx_race", sources: "bx_sources", measure: "bx_measure", measures: "bx_home"})[k] || "bx_home";
  if (rel === "night/") return "n_home";
  if (rel === "night/sky/") return "n_sky";
  if (rel === "reading-room/") return "rr_room";
  if (rel === "night/us/") return ({state: "nu_state", race: "n_race"})[k] || "nu_home";
  if (rel === "night/feed/") return ({how: "n_feed_how"})[k] || "n_feed";
  if (rel === "night/forecasts/") return ({track: "n_fc_track", method: "n_fc_method"})[k] || "n_fc";
  if (rel === "night/forecasts/record/") return "n_fc_record";
  if (rel === "night/past/") return ({st: "n_past_list", c: "n_past_contest"})[k] || "n_past";
  if (/^night\/[a-z]{2}\/$/.test(rel)) return ({statewide: "nx_list", legislature: "nx_list", courts: "nx_list", counties: "nx_counties",
    county: "nx_counties", race: "n_race", mine: "nx_mine", yours: "nx_mine"})[k] || "nx_home";
  if (/^[a-z]{2}\/$/.test(rel)) return ({map: "st_map", shapes: "st_shapes", shape: "st_shapes", people: "st_people", members: "st_members",
    member: "st_member", sources: "st_sources"})[k] || "st_home";
  return "other";
}

export function guideFor(rel, hash) { return E[where(rel, hash)]; }

const esc = s => String(s).replace(/[&<>"]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"})[c]);

/* the guide as HTML. `root` is the way from the page to the site's root; an address that starts with # stays on the page */
export function guideHTML(g, root) {
  const href = u => u.startsWith("#") ? u : root + u;
  return `<p class="tca-g-t"><b>${esc(t(g.t))}</b><br>${esc(t(g.a))}</p>` +
    `<ol class="tca-g-s">${g.s.map(x => `<li>${esc(t(x))}</li>`).join("")}</ol>` +
    (g.n && g.n.length ? `<p class="tca-g-n">${esc(t("Next:"))} ${g.n.map(([l, u]) => `<a href="${esc(href(u))}">${esc(t(l))}</a>`).join(" &middot; ")}</p>` : "");
}
